/**
 * @name ReDoS in glob implementation
 * @description Checks for regular expressions created from function arguments, which might lead to ReDoS.
 * @kind problem
 * @problem.severity warning
 * @id py/redos-glob
 * @tags security
 *       external/cwe/cwe-1333
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module ReDoSConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("re").getMember(["compile", "match", "search", "findall", "finditer", "fullmatch", "split", "sub", "subn"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module ReDoSFlow = TaintTracking::Global<ReDoSConfig>;

from DataFlow::Node source, DataFlow::Node sink
where ReDoSFlow::flow(source, sink)
select sink, "Potential ReDoS: Regular expression constructed from parameter $@.", source, source.toString()
